#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');
const { validate } = require('../lib/validator');

function readJson(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  return JSON.parse(raw);
}

function main(argv) {
  const [dataPath, schemaPath] = argv;

  if (!dataPath || !schemaPath) {
    console.error('Usage: validate <data.json> <schema.json>');
    process.exit(1);
  }

  let data;
  let schema;

  try {
    data = readJson(path.resolve(dataPath));
  } catch (err) {
    console.error(`FAIL\nCould not read/parse data file "${dataPath}": ${err.message}`);
    process.exit(1);
  }

  try {
    schema = readJson(path.resolve(schemaPath));
  } catch (err) {
    console.error(`FAIL\nCould not read/parse schema file "${schemaPath}": ${err.message}`);
    process.exit(1);
  }

  const errors = validate(data, schema);

  if (errors.length === 0) {
    console.log('PASS');
    process.exit(0);
  } else {
    console.log('FAIL');
    for (const error of errors) {
      console.error(`  - ${error}`);
    }
    process.exit(1);
  }
}

if (require.main === module) {
  main(process.argv.slice(2));
}

module.exports = { main };

'use strict';

const TYPE_CHECKS = {
  string: (v) => typeof v === 'string',
  number: (v) => typeof v === 'number' && !Number.isNaN(v),
  integer: (v) => typeof v === 'number' && Number.isInteger(v),
  boolean: (v) => typeof v === 'boolean',
  object: (v) => typeof v === 'object' && v !== null && !Array.isArray(v),
  array: (v) => Array.isArray(v),
  null: (v) => v === null,
};

/**
 * Validate `data` against a minimal JSON Schema subset supporting
 * type, required, and properties (recursively for nested objects).
 * Returns an array of human-readable error strings; empty array means valid.
 */
function validate(data, schema, path = '$') {
  const errors = [];

  if (schema.type) {
    const types = Array.isArray(schema.type) ? schema.type : [schema.type];
    const matches = types.some((type) => {
      const check = TYPE_CHECKS[type];
      return check ? check(data) : true;
    });
    if (!matches) {
      errors.push(`${path}: expected type ${types.join(' or ')}, got ${describeType(data)}`);
      return errors;
    }
  }

  if (schema.required && Array.isArray(schema.required)) {
    if (TYPE_CHECKS.object(data)) {
      for (const key of schema.required) {
        if (!Object.prototype.hasOwnProperty.call(data, key)) {
          errors.push(`${path}: missing required property "${key}"`);
        }
      }
    }
  }

  if (schema.properties && TYPE_CHECKS.object(data)) {
    for (const [key, subSchema] of Object.entries(schema.properties)) {
      if (Object.prototype.hasOwnProperty.call(data, key)) {
        errors.push(...validate(data[key], subSchema, `${path}.${key}`));
      }
    }
  }

  if (schema.items && TYPE_CHECKS.array(data)) {
    data.forEach((item, index) => {
      errors.push(...validate(item, schema.items, `${path}[${index}]`));
    });
  }

  return errors;
}

function describeType(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

module.exports = { validate };

{
  "name": "json-schema-validate-cli",
  "version": "1.0.0",
  "description": "A Node.js CLI that validates a JSON file against a JSON Schema file and prints PASS or FAIL",
  "main": "bin/validate.js",
  "bin": {
    "validate": "bin/validate.js"
  },
  "scripts": {
    "test": "node --test test/validator.test.js"
  },
  "license": "MIT"
}

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { validate } = require('../lib/validator');

test('passes when data matches schema (type, required, properties)', () => {
  const schema = {
    type: 'object',
    required: ['name', 'age'],
    properties: {
      name: { type: 'string' },
      age: { type: 'integer' },
    },
  };
  const data = { name: 'Ada', age: 30 };

  const errors = validate(data, schema);

  assert.deepEqual(errors, []);
});

test('fails when a required property is missing', () => {
  const schema = {
    type: 'object',
    required: ['name', 'age'],
    properties: {
      name: { type: 'string' },
      age: { type: 'integer' },
    },
  };
  const data = { name: 'Ada' };

  const errors = validate(data, schema);

  assert.equal(errors.length, 1);
  assert.match(errors[0], /missing required property "age"/);
});

test('fails when a property has the wrong type', () => {
  const schema = {
    type: 'object',
    properties: {
      age: { type: 'integer' },
    },
  };
  const data = { age: 'thirty' };

  const errors = validate(data, schema);

  assert.equal(errors.length, 1);
  assert.match(errors[0], /expected type integer, got string/);
});
